    private static Runtime runtime(Path profile,Limits limits)throws IOException {
        if(!Files.isRegularFile(profile))throw new Unavailable("Missing exact original network runtime profile: "+profile);Map<?,?> r=object(json(profile,134217728));keys(r,"schema_version","status","source_label","rscript","r_home","libraries","source_root","python","python_home","python_base","files","setup_receipts","scope");integer(r.get("schema_version"),1,1);equal(r,"status","validated-original-cellchat-network-runtime-profile-only");equal(r,"source_label","1.1.3");Path base=profile.getParent();Path source=path(base,r.get("source_root")),exe=path(base,r.get("rscript")),home=path(base,r.get("r_home")),python=path(base,r.get("python")),pythonHome=path(base,r.get("python_home")),pythonBase=path(base,r.get("python_base"));var libraries=new ArrayList<Path>();for(Object p:list(r.get("libraries")))libraries.add(path(base,p));require(!libraries.isEmpty()&&libraries.size()<=32,"Invalid original R library population");
        for(Path p:List.of(exe,python))if(!Files.isRegularFile(p))throw new Unavailable("Missing exact original executable: "+p);for(Path p:List.of(source,home,pythonHome,pythonBase))if(!Files.isDirectory(p))throw new Unavailable("Missing declared runtime/source root: "+p);for(Path p:libraries)if(!Files.isDirectory(p))throw new Unavailable("Missing declared private R library: "+p);
        Map<?,?> declared=object(r.get("files"));require(declared.size()<=limits.files(),"Runtime file count capacity exceeded");var files=new LinkedHashMap<Path,Pin>();long total=0;
        for(var entry:declared.entrySet()){Path p=path(base,entry.getKey());require(p.startsWith(home)||p.startsWith(pythonHome)||p.startsWith(pythonBase)||libraries.stream().anyMatch(p::startsWith),"Runtime file outside declared roots");Pin value=fingerprint(entry.getValue(),limits.runtimeBytes());total=Math.addExact(total,value.bytes());require(total<=limits.runtimeBytes()&&files.put(p,value)==null,"Duplicate/over-capacity original runtime inventory");}
        require(files.containsKey(exe)&&files.containsKey(python),"Unbound R/Python executable");return new Runtime(source,exe,home,List.copyOf(libraries),python,pythonHome,pythonBase,Map.copyOf(files));
    }
    private static void verifyRuntime(Runtime runtime,Limits limits)throws IOException {
        var executor=java.util.concurrent.Executors.newFixedThreadPool(8);var futures=new ArrayList<java.util.concurrent.Future<Void>>();
        try {for(var e:runtime.files.entrySet())futures.add(executor.submit(()->{if(!Files.isRegularFile(e.getKey()))throw new Unavailable("Missing original runtime file: "+e.getKey());require(e.getValue().equals(pin(e.getKey(),e.getValue().bytes(),()->{})),"Changed original runtime file: "+e.getKey());return null;}));for(var future:futures)try{future.get();}catch(java.util.concurrent.ExecutionException failed){if(failed.getCause() instanceof IOException io)throw io;throw new IOException("Runtime read failed",failed.getCause());}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IOException("Runtime read interrupted",interrupted);}}
        finally{for(var f:futures)if(!f.isDone())f.cancel(true);executor.shutdownNow();}
        for(Path root:runtime.libraries)checkPopulation(root,runtime.files,null);checkPopulation(runtime.pythonHome,runtime.files,null);checkPopulation(runtime.pythonBase.resolve("Lib"),runtime.files,runtime.pythonBase.resolve("Lib/site-packages"));checkPopulation(runtime.pythonBase.resolve("DLLs"),runtime.files,null);require(runtime.files.size()<=limits.files(),"Runtime count capacity exceeded");
    }
    private static void checkPopulation(Path root,Map<Path,Pin> files,Path excluded)throws IOException {
        Files.walkFileTree(root,new java.nio.file.SimpleFileVisitor<>() {
            @Override public java.nio.file.FileVisitResult preVisitDirectory(Path dir,java.nio.file.attribute.BasicFileAttributes a)throws IOException {require(!Files.isSymbolicLink(dir),"Linked runtime directory refused");return excluded!=null&&dir.equals(excluded)?java.nio.file.FileVisitResult.SKIP_SUBTREE:java.nio.file.FileVisitResult.CONTINUE;}
            @Override public java.nio.file.FileVisitResult visitFile(Path file,java.nio.file.attribute.BasicFileAttributes a)throws IOException {require(a.isRegularFile()&&!Files.isSymbolicLink(file)&&files.containsKey(file),"Unbound/linked runtime file: "+file);return java.nio.file.FileVisitResult.CONTINUE;}
        });
    }
    private static void captureParent(Path source,Path target,Limits limits)throws IOException {Map<String,Object> wanted=inventory(source);require(wanted.size()<=limits.files(),"Parent file count capacity exceeded");long size=0;for(Object p:wanted.values())size=Math.addExact(size,fingerprint(p,limits.inputBytes()).bytes());require(size<=limits.inputBytes(),"Complete parent byte capacity exceeded");Files.createDirectories(target);for(String name:wanted.keySet()){Path file=target.resolve(name);Files.createDirectories(file.getParent());Files.copy(source.resolve(name),file);}require(inventory(target).equals(wanted)&&inventory(source).equals(wanted),"Parent changed during complete capture");}
    private static Map<String,Object> inventory(Path root)throws IOException {var result=new TreeMap<String,Object>();try(var paths=Files.walk(root)){for(Path p:paths.toList()){require(!Files.isSymbolicLink(p),"Linked result/parent entry refused");if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)){Pin value=pin(p,Long.MAX_VALUE,()->{});result.put(root.relativize(p).toString().replace('\\','/'),Map.of("bytes",value.bytes(),"sha256",value.sha256()));}}}return result;}
    private static void bounds(Path root,Limits limits)throws IOException {long total=0,count=0;try(var paths=Files.walk(root)){for(Path file:paths.toList()){require(!Files.isSymbolicLink(file),"Linked network output refused");if(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)){try{total=Math.addExact(total,Files.size(file));count++;}catch(java.nio.file.NoSuchFileException replaced){continue;}require(count<=limits.files()&&total<=limits.outputBytes(),"Network output byte/file capacity exceeded");}}}}
    private static byte[] resource(String name)throws IOException {try(var stream=CellChatNetworkCli.class.getResourceAsStream(RESOURCE+name)){require(stream!=null,"Missing packaged network resource");byte[] raw=stream.readNBytes(2097153);require(raw.length<=2097152,"Network resource capacity exceeded");return raw;}}
    private static Path resolved(Path p)throws IOException {var missing=new java.util.ArrayDeque<Path>();Path current=p.toAbsolutePath().normalize();while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"No existing output ancestor");missing.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path part:missing)current=current.resolve(part);return current.normalize();}
    private static void overlap(Path out,Path input)throws IOException {Path p=resolved(input);require(!out.startsWith(p)&&!p.startsWith(out),"Output overlaps protected parent/runtime/source");}
    private static boolean stopOwned(Process process,Map<Long,ProcessHandle> children) {
        process.descendants().forEach(p->children.putIfAbsent(p.pid(),p));
        var handles=new ArrayList<>(children.values());
        for(int i=handles.size()-1;i>=0;i--)if(handles.get(i).isAlive())handles.get(i).destroyForcibly();
        if(process.isAlive())process.destroyForcibly();
        try {
            process.waitFor(10,TimeUnit.SECONDS);
            for(ProcessHandle child:handles)if(child.isAlive())try{child.onExit().get(10,TimeUnit.SECONDS);}catch(java.util.concurrent.ExecutionException|java.util.concurrent.TimeoutException failure){return false;}
        }catch(InterruptedException interrupted){Thread.currentThread().interrupt();return false;}
        return !process.isAlive()&&handles.stream().noneMatch(ProcessHandle::isAlive);
    }
    static void verifyBundle(Path root)throws IOException {
        Map<?,?> done=object(json(root.resolve("COMPLETED.json"),134217728));require(Boolean.TRUE.equals(done.get("result_admitted"))&&text(done.get("status")).equals("completed-original-cellchat-network-with-source-warnings"),"No admitted complete original network result");Map<?,?> files=object(done.get("files"));require(inventoryExceptCompletion(root).equals(files),"Complete network file population/hash differs");
        Map<?,?> state=object(json(root.resolve("analysis-status.json"),1048576));require(Boolean.TRUE.equals(state.get("result_admitted"))&&state.get("status").equals(done.get("status"))&&ACTION.equals(state.get("required_action")),"Network admission protocol differs");require(integer(object(json(root.resolve("process.json"),1048576)).get("exit_code"),0,0)==0&&Boolean.TRUE.equals(object(json(root.resolve("owned-children.json"),1048576)).get("all_terminal")),"Original network process/worker disposition differs");
        require(sha(resource("worker.R")).equals(sha(bytes(root.resolve("worker-source.R"),2097152)))&&sha(resource("SOURCE-LOCK.json")).equals(sha(bytes(root.resolve("source-lock.json"),2097152))),"Unsupported captured network worker/source");Request request=CellChatNetworkRequest.parse(json(root.resolve("source-request.json"),1048576),root);Path parent=root.resolve("inputs/parent");CellChatLegacyCli.verifyBundle(parent);Map<String,Object> audit=CellChatNetworkAudit.verify(root.resolve("results"),parent,request);require(NextflowJson.json(audit).equals(NextflowJson.json(json(root.resolve("provenance.json"),16777216))),"Native network provenance replay differs");long rng=((Number)audit.get("original_parallel_rng_warnings")).longValue();require(integer(state.get("original_parallel_rng_warnings"),0,1000000)==rng,"Original RNG warning census differs");String warning=utf8(bytes(root.resolve("WARNINGS.md"),16777216));require(warning.startsWith("# "+done.get("status"))&&warning.contains(SCOPE)&&warning.contains(ACTION)&&warning.contains("PARENT SOURCE DIAGNOSTICS RETAINED")&&warning.contains("ORIGINAL UMAP REPRODUCIBILITY WARNING"),"Prominent network/parent warning actions missing");if(rng>0)require(warning.contains("original_parallel_rng_warnings="+rng),"Original RNG misuse warning missing");for(var field:object(audit.get("parent_original_source_diagnostics")).entrySet())require(warning.contains(field.getKey()+"="+field.getValue()),"Parent source diagnostic missing from new warning report");
    }
    private static Map<String,Object> inventoryExceptCompletion(Path root)throws IOException {var values=new TreeMap<String,Object>(inventory(root));values.remove("COMPLETED.json");return values;}
